UPDATE public.productos SET
  descripcion_larga_es = 'Monitor multiparámetro portátil con batería de 15 horas de autonomía, diseñado para el monitoreo continuo de signos vitales en entornos clínicos y ambulatorios. Integra configuraciones configurables de SpO2, NIBP, ECG y temperatura, con opciones de conectividad Bluetooth y LAN/CMS inalámbrico. Su pantalla LCD TFT de 8.4" y registrador térmico facilitan la documentación clínica en tiempo real.',
  descripcion_larga_en = 'Portable multi-parameter monitor with 15-hour battery life, designed for continuous vital signs monitoring in clinical and outpatient settings. Integrates configurable SpO2, NIBP, ECG and temperature settings, with Bluetooth and wireless LAN/CMS connectivity options. Its 8.4" TFT LCD screen and thermal printer facilitate real-time clinical documentation.',
