UPDATE public.productos SET
  descripcion_larga_es = 'Arco en C con generador de alta frecuencia de 5 kW y detector digital de 205×205 mm, diseñado para procedimientos de fluoroscopia y radiografía digital. Su estación de trabajo DR y dos pantallas táctiles optimizan el flujo de trabajo en entornos quirúrgicos y de intervencionismo. El carro con pantalla de 30 pulgadas mejora la visualización y ergonomía durante su uso.',
