UPDATE public.productos SET
  descripcion_larga_es = 'Máquina de anestesia con pantalla TFT de 8.4" y seis tubos caudal para tres gases, ofreciendo circuitos PPSU/metálicos y bypass de cal sodada para máxima flexibilidad. Sus modos ventilatorios neonatales, pediátricos y adultos, junto con el calentador de circuito, garantizan un suministro preciso y seguro de anestésicos. El ACGO de alta visibilidad mejora la seguridad durante procedimientos quirúrgicos.',
  descripcion_larga_en = 'Anesthesia machine with 8.4" TFT screen and six flow tubes for three gases, offering PPSU/metallic circuits and soda lime bypass for maximum flexibility. Its neonatal, pediatric and adult ventilation modes, along with circuit heater, ensure precise and safe anesthetic delivery. High-visibility ACGO enhances safety during surgical procedures.',
