UPDATE public.productos SET
  descripcion_larga_es = 'Máquina de anestesia con pantalla táctil TFT de 15.6" y monitor de paciente integrado, combinando control electrónico completo y caudalímetro electrónico en una sola unidad. Sus modos ventilatorios neonatales, pediátricos y adultos, junto con el calentador de circuito y luces LED, optimizan la experiencia en quirófano. La construcción en acero inoxidable asegura durabilidad y fácil limpieza.',
  descripcion_larga_en = 'Anesthesia machine with 15.6" touchscreen TFT display and integrated patient monitor, combining full electronic control and electronic flowmeter in a single unit. Its neonatal, pediatric and adult ventilation modes, along with circuit heater and LED lights, optimize the operating room experience. Stainless steel construction ensures durability and easy cleaning.',
