UPDATE public.productos SET
  descripcion_larga_es = 'El sistema DR montado en suelo incorpora un detector panel plano inalámbrico HD que elimina cables y optimiza la movilidad. Su estructura de doble columna proporciona estabilidad para posiciones en pie, acostado, lateral, oblicuo, camilla y silla de ruedas. El control eléctrico de todos los movimientos asegura un posicionamiento preciso y rápido.',
  descripcion_larga_en = 'The floor-mounted DR system incorporates a wireless HD flat panel detector that eliminates cables and optimizes mobility. Its dual-column structure provides stability for standing, supine, lateral, oblique, table, and wheelchair positions. Electric control of all movements ensures precise and fast positioning.',
