UPDATE public.productos SET
  descripcion_larga_es = 'El sistema DR móvil está diseñado para llevar la radiografía digital al punto de atención, con pantalla táctil de 19 pulgadas y detector FPD inalámbrico. Permite exposición retardada y remota, capturando hasta 1200 películas continuas con una autonomía de 30 km. Incluye cámara HD con audio, medición láser de distancia SID y modo de sueño para ahorro energético.',
  descripcion_larga_en = 'The mobile DR system is designed to bring digital radiography to the point of care, featuring a 19-inch touchscreen and wireless FPD detector. It allows delayed and remote exposure, capturing up to 1200 continuous frames with a 30 km range. Includes HD camera with audio, SID laser distance measurement, and sleep mode for energy saving.',
