UPDATE public.productos SET
  descripcion_larga_es = 'El DR Dinámico de Brazo-UC es el primer sistema del mundo con brazo-UC y detector FPD dinámico HD, ofreciendo fluoroscopia digital y radiografía con costura de imágenes. Su detector con capa CsI de 600 micrones proporciona alta sensibilidad y resolución espacial. Es ideal para exámenes de contraste digital y neumoconiosis.',
  descripcion_larga_en = 'The Dynamic DR with UC Arm is the world''s first system with UC arm and dynamic HD FPD detector, offering digital fluoroscopy and radiography with image stitching. Its detector with 600-micron CsI layer provides high sensitivity and spatial resolution. It is ideal for digital contrast examinations and pneumoconiosis.',
