UPDATE public.productos SET
  descripcion_larga_es = 'El Monitor de Paciente Biolight S12 integra tecnología inteligente, diseño ergonómico y una interfaz de usuario moderna para brindar monitoreo clínico confiable en todos los niveles de atención.

Equipado con una pantalla multitáctil HD de 12.1 pulgadas, el S12 permite visualizar múltiples parámetros vitales de forma clara e intuitiva, optimizando la eficiencia del personal médico.

Preconfigurado para pacientes adultos, pediátricos y neonatales, mide de manera precisa ECG, SpO₂, presión arterial no invasiva (NIBP), temperatura y frecuencia respiratoria, con opciones para incorporar CO₂, IBP y gasto cardíaco (C.O.) según las necesidades clínicas.

Gracias a su software de última generación, conectividad IoT y diseño ergonómico, el S12 garantiza monitoreo continuo, precisión diagnóstica y operación simplificada en entornos como quirófanos, UCIs, salas de recuperación y urgencias.

Una herramienta versátil que combina rendimiento clínico, tecnología de vanguardia y facilidad de uso, respaldada por la confiabilidad Biolight.',
  descripcion_larga_en = 'The Biolight S12 Patient Monitor integrates intelligent technology, ergonomic design, and a modern user interface for reliable clinical monitoring across all care levels. Its 12.1-inch HD multitouch display provides clear, intuitive visualization of multiple vital parameters, enhancing clinical staff efficiency. Preconfigured for adult, pediatric, and neonatal patients, it accurately measures ECG, SpO₂, non-invasive blood pressure (NIBP), temperature, and respiratory rate, with options to add CO₂, IBP, and cardiac output (C.O.). Advanced software, IoT connectivity, and ergonomic design ensure continuous monitoring, diagnostic accuracy, and simplified operation in operating rooms, ICUs, recovery rooms, and emergency departments.',
  atributos = COALESCE(atributos, '{}'::jsonb) || '{"beneficios_es": ["Monitor de paciente Biolight S12 con pantalla multitáctil HD de 12.1 pulgadas. Mide ECG, SpO₂, NIBP, temperatura y frecuencia respiratoria en adultos, pediátricos y neonatales. Precio bajo cotización.", "Dato de ficha/catálogo: Modelo: S12.", "Dato de ficha/catálogo: Pantalla: Multitáctil HD de 12.1 pulgadas.", "Dato de ficha/catálogo: Población: Adultos, pediátricos y neonatales."], "beneficios_en": ["Biolight S12 patient monitor with a 12.1-inch HD multitouch display. Measures ECG, SpO₂, NIBP, temperature and respiratory rate for adult, pediatric and neonatal patients. Price on request.", "Catalog/spec field: Modelo: S12.", "Catalog/spec field: Pantalla: Multitáctil HD de 12.1 pulgadas.", "Catalog/spec field: Población: Adultos, pediátricos y neonatales."], "valor_es": "Monitor de paciente Biolight S12 para evaluación institucional (Biolight); Monitor de paciente Biolight S12 con pantalla multitáctil HD de 12.1 pulgadas.. Cotización y validación de ficha con I-ME; sin inventar prestaciones no documentadas.", "valor_en": "Biolight S12 patient monitor for institutional evaluation (Biolight); Biolight S12 patient monitor with a 12.1-inch HD multitouch display.. Quoting and datasheet validation with I-ME; no undocumented claims.", "preguntas_frecuentes_es": [{"q": "¿Cómo cotizar Monitor de paciente Biolight S12 para mi institución?", "a": "Solicite cotización en esta página o por WhatsApp I-ME. Indicamos disponibilidad, plazo y documentación del fabricante Biolight."}, {"q": "¿Hay ficha técnica PDF de Monitor de paciente Biolight S12?", "a": "En este momento no hay PDF publicado en la ficha web. I-ME gestiona la ficha oficial del fabricante al cotizar, sin inventar especificaciones."}, {"q": "¿Qué problema resuelve Monitor de paciente Biolight S12 en piso o servicio?", "a": "Monitor de paciente Biolight S12 con pantalla multitáctil HD de 12.1 pulgadas. Mide ECG, SpO₂, NIBP, temperatura y frecuencia respiratoria en adultos, pediátricos y neonatales. Precio bajo cotización. La adecuación exacta se confirma con contexto clínico-operativo en asesoría I-ME."}, {"q": "¿Qué datos técnicos están publicados para Monitor de paciente Biolight S12?", "a": "En catálogo constan: Modelo: S12; Pantalla: Multitáctil HD de 12.1 pulgadas; Población: Adultos, pediátricos y neonatales; Parámetros estándar: ECG, SpO₂, presión arterial no invasiva (NIBP), temperatura y frecuencia respiratoria. Cualquier otro dato se valida con ficha oficial al cotizar."}, {"q": "¿Monitor de paciente Biolight S12 es del fabricante Biolight?", "a": "Sí: la referencia se asocia a Biolight. El canal comercial y de soporte en Colombia es I-ME."}], "preguntas_frecuentes_en": [{"q": "How do I quote Biolight S12 patient monitor for my institution?", "a": "Request a quote on this page or via I-ME WhatsApp. We confirm availability, lead time and manufacturer documentation from Biolight."}, {"q": "Is there a PDF datasheet for Biolight S12 patient monitor?", "a": "No PDF is published on this web sheet yet. I-ME obtains the official manufacturer datasheet when quoting — without inventing specs."}, {"q": "What floor/service problem does Biolight S12 patient monitor address?", "a": "Biolight S12 patient monitor with a 12.1-inch HD multitouch display. Measures ECG, SpO₂, NIBP, temperature and respiratory rate for adult, pediatric and neonatal patients. Price on request. Exact fit is confirmed with clinical-operational context in I-ME advisory."}, {"q": "Which technical data are published for Biolight S12 patient monitor?", "a": "Catalog lists: Modelo: S12; Pantalla: Multitáctil HD de 12.1 pulgadas; Población: Adultos, pediátricos y neonatales; Parámetros estándar: ECG, SpO₂, presión arterial no invasiva (NIBP), temperatura y frecuencia respiratoria. Any further data is validated with the official datasheet when quoting."}, {"q": "Is Biolight S12 patient monitor from manufacturer Biolight?", "a": "Yes: the reference is associated with Biolight. Commercial and support channel in Colombia is I-ME."}], "seo_keywords_es": ["monitor de paciente biolight s12", "biolight", "cotización", "equipo hospitalario", "I-ME Colombia"], "seo_keywords_en": ["biolight s12 patient monitor", "biolight", "quote", "hospital equipment", "I-ME Colombia"], "enriquecimiento": {"tipo": "sin_ficha_pdf", "fecha": "2026-10-18", "nota": "Landing ligera sin inventar specs; PDF pendiente de fabricante"}, "marca": "Biolight", "fabricante": "Biolight"}'::jsonb
