UPDATE public.productos SET
  descripcion_larga_es = 'El equipo móvil Lingxi integra un generador de alta frecuencia y un detector de panel plano digital que permiten la captura de imágenes en modo estático y dinámico, con módulo de análisis funcional pulmonar orientado a ventilación, perfusión y volúmenes. Su brazo de posicionamiento y su base sobre ruedas facilitan la maniobra en pasillos estrechos, camas de hospitalización y áreas de urgencia. El control exclusivo mediante un mando de una mano optimiza la operación sin necesidad de desplazamiento del operador.',
  descripcion_larga_en = 'The Lingxi mobile unit integrates a high-frequency generator and a digital flat-panel detector that enable image capture in static and dynamic modes, with a pulmonary functional analysis module focused on ventilation, perfusion, and volumes. Its positioning arm and wheeled base facilitate maneuvering in narrow hallways, hospital beds, and emergency areas. Exclusive one-hand control optimizes operation without requiring the operator to move.',
