UPDATE public.productos SET
  descripcion_larga_es = 'El sistema Changfeng montado en techo dispone de un detector de gran formato de 47 pulgadas que permite la captura de columna vertebral completa y miembros inferiores completos en una sola exposición, eliminando la necesidad de múltiples proyecciones. El seguimiento bidireccional automático sincroniza el movimiento del tubo de rayos X y el detector, mientras que la función de stitching angular reconstruye imágenes de gran campo.',
  descripcion_larga_en = 'The Changfeng ceiling-mounted system features a large-format 47-inch detector that enables capture of the full spine and complete lower limbs in a single exposure, eliminating the need for multiple projections. Automatic bidirectional tracking synchronizes the movement of the X-ray tube and detector, while the angular stitching function reconstructs wide-field images.',
  atributos = COALESCE(atributos, '{}'::jsonb) || '{"beneficios_es": ["Sistema de radiografía digital de techo con detector de gran formato de 47\" que permite columna completa y miembros inferiores completos en una sola exposición, con seguimiento bidireccional automático y stitching angular."], "beneficios_en": ["Ceiling-mounted digital radiography system with a 47-inch large-format detector for full-spine and full-lower-limb imaging in a single exposure, with bidirectional auto-tracking and automatic angular stitching."], "valor_es": "Sistema de Radiografía Digital Dinámica de Techo Changfeng para evaluación institucional; Sistema de radiografía digital de techo con detector de gran formato de 47\" que permite columna completa y miembros inferiores completos en una sola exposición, con seguimiento bidireccional automático y stitching angular.. Cotización y validación de ficha con I-ME; sin inventar prestaciones no documentadas.", "valor_en": "Changfeng Series Ceiling-Mounted Dynamic DR for institutional evaluation; Ceiling-mounted digital radiography system with a 47-inch large-format detector for full-spine and full-lower-limb imaging in a single exposure, with bidirectional auto-tracking and automatic angular stitching.. Quoting and datasheet validation with I-ME; no undocumented claims.", "preguntas_frecuentes_es": [{"q": "¿Cómo cotizar Sistema de Radiografía Digital Dinámica de Techo Changfeng para mi institución?", "a": "Solicite cotización en esta página o por WhatsApp I-ME. Indicamos disponibilidad, plazo y documentación del fabricante."}, {"q": "¿Hay ficha técnica PDF de Sistema de Radiografía Digital Dinámica de Techo Changfeng?", "a": "En este momento no hay PDF publicado en la ficha web. I-ME gestiona la ficha oficial del fabricante al cotizar, sin inventar especificaciones."}, {"q": "¿Qué problema resuelve Sistema de Radiografía Digital Dinámica de Techo Changfeng en piso o servicio?", "a": "Sistema de radiografía digital de techo con detector de gran