UPDATE public.productos SET
  descripcion_larga_es = 'El sistema DTP580 combina arco en U compacto con detector giratorio paraVersiones de radiografía digital, fluoroscopia y estudios contrastados en un solo equipo. La función de stitching de cuerpo completo amplía el campo de adquisición para valoraciones ortopédicas y posturales, mientras que el modo de neumoconiosis está optimizado para la detección de opacidades pulmonares. El posicionamiento modular reduce el espacio físico necesario en sala.',
  descripcion_larga_en = 'The DTP580 system combines a compact U-shaped arm with a rotating detector for digital radiography, fluoroscopy, and contrast-enhanced studies in a single unit. The full-body stitching function expands the acquisition field for orthopedic and postural assessments, while the pneumoconiosis mode is optimized for detecting pulmonary opacities. Modular positioning reduces the physical space required in the room.',
  atributos = COALESCE(atributos, '{}'::jsonb) || '{"beneficios_es": ["Sistema multifuncional de radiografía digital con arco en U y detector giratorio, para fluoroscopia, radiografía, estudios con contraste, stitching de cuerpo completo y neumoconiosis."], "beneficios_en": ["Multifunctional digital radiography system with a U-shaped arm and rotating detector, for fluoroscopy, radiography, contrast studies, full-body stitching and pneumoconiosis exams."], "valor_es": "Sistema de Radiografía Digital Dinámica UC-ARM DTP580 para evaluación institucional; Sistema multifuncional de radiografía digital con arco en U y detector giratorio, para fluoroscopia, radiografía, estudios con contraste, stitching de cuerpo completo y neumoconiosis.. Cotización y validación de ficha con I-ME; sin inventar prestaciones no documentadas.", "valor_en": "DTP580 Series UC-ARM Dynamic DR System for institutional evaluation; Multifunctional digital radiography system with a U-shaped arm and rotating detector, for fluoroscopy, radiography, contrast studies, full-body stitching and pneumoconiosis exams.. Quoting and datasheet validation with I-ME; no undocumented claims.", "preguntas_frecuentes_es": [{"q": "¿Cómo cotizar Sistema de Radiografía Digital Dinámica UC-ARM DTP580 para mi institución?", "a": "Solicite cotización en esta página o por WhatsApp I-ME. Indicamos disponibilidad, plazo y documentación del fabricante."}, {"q": "¿Hay ficha técnica PDF de Sistema de Radiografía Digital Dinámica UC-ARM DTP580?", "a": "En este momento no hay PDF publicado en la ficha web. I-ME gestiona la ficha oficial del fabricante al cotizar, sin inventar especificaciones."}, {"q": "¿Qué problema resuelve Sistema de Radiografía Digital Dinámica UC-ARM DTP580 en piso o servicio?", "a": "Sistema multifuncional de radiografía digital con arco en U y detector giratorio, para fluoroscopia, radiografía, estudios con contraste, stitching de cuerpo completo y neumoconiosis. La adecuación exacta se confirma con contexto clínico-operativo en asesoría I-ME."}], "preguntas_frecuentes_en": [{"q": "How do I quote DTP580 Series UC-ARM Dynamic DR System for my institution?", "a": "Request a quote on this page or via I-ME WhatsApp. We confirm availability, lead time and manufacturer documentation."}, {"q": "Is there a PDF datasheet for DTP580 Series UC-ARM Dynamic DR System?", "a": "No PDF is published on this web sheet yet. I-ME obtains the official manufacturer datasheet when quoting — without inventing specs."}, {"q": "What floor/service problem does DTP580 Series UC-ARM Dynamic DR System address?", "a": "Multifunctional digital radiography system with a U-shaped arm and rotating detector, for fluoroscopy, radiography, contrast studies, full-body stitching and pneumoconiosis exams. Exact fit is confirmed with clinical-operational context in I-ME advisory."}], "seo_keywords_es": ["sistema de radiografía digital dinámica uc-arm dtp580", "cotización", "equipo hospitalario", "I-ME Colombia"], "seo_keywords_en": ["dtp580 series uc-arm dynamic dr system", "quote", "hospital equipment", "I-ME Colombia"], "enriquecimiento": {"tipo": "sin_ficha_pdf", "fecha": "2026-10-18", "nota": "Landing ligera sin inventar specs; PDF pendiente de fabricante"}}'::jsonb
