UPDATE public.productos SET
  descripcion_larga_es = 'El sistema MTP montado en piso incorpora mesa flotante de cuatro movimientos con superficie antideslizante y generador de alta frecuencia compacto. La columna de tubo giratoria permite acceso lateral y frontal, compatible con camillas de traslado y sillas de ruedas sin necesidad de transferencias repetitivas del paciente. El seguimiento eléctrico sincronizado mantiene la alineación tubo-detector durante el movimiento.',
  descripcion_larga_en = 'The MTP floor-mounted system incorporates a four-way floating table with non-slip surface and compact high-frequency generator. The rotating tube column allows lateral and frontal access, compatible with stretchers and wheelchairs without the need for repetitive patient transfers. The electrically synchronized tracking maintains tube-detector alignment during movement.',
  atributos = COALESCE(atributos, '{}'::jsonb) || '{"beneficios_es": ["Sistema radiográfico de piso con mesa flotante de cuatro movimientos, seguimiento eléctrico sincronizado entre el tubo de rayos X y el detector, y columna giratoria compatible con camilla y silla de ruedas."], "beneficios_en": ["Floor-mounted radiographic system with a four-way floating table, electrically synchronized tracking between the X-ray tube and detector, and a rotating column compatible with stretcher and wheelchair exams."], "valor_es": "Sistema Radiográfico de Piso MTP para evaluación institucional; Sistema radiográfico de piso con mesa flotante de cuatro movimientos, seguimiento eléctrico sincronizado entre el tubo de rayos X y el detector, y columna giratoria compatible con camilla y silla de ruedas.. Cotización y validación de ficha con I-ME; sin inventar prestaciones no documentadas.", "valor_en": "MTP Series Floor-Mounted Radiographic System for institutional evaluation; Floor-mounted radiographic system with a four-way floating table, electrically synchronized tracking between the X-ray tube and detector, and a rotating column compatible with stretcher and wheelchair exams.. Quoting and datasheet validation with I-ME; no undocumented claims.", "preguntas_frecuentes_es": [{"q": "¿Cómo cotizar Sistema Radiográfico de Piso MTP para mi institución?", "a": "Solicite cotización en esta página o por WhatsApp I-ME. Indicamos disponibilidad, plazo y documentación del fabricante."}, {"q": "¿Hay ficha técnica PDF de Sistema Radiográfico de Piso MTP?", "a": "En este momento no hay PDF publicado en la ficha web. I-ME gestiona la ficha oficial del fabricante al cotizar, sin inventar especificaciones."}, {"q": "¿Qué problema resuelve Sistema Radiográfico de Piso MTP en piso o servicio?", "a": "Sistema radiográfico de piso con mesa flotante de cuatro movimientos, seguimiento eléctrico sincronizado entre el tubo de rayos X y el detector, y columna giratoria compatible con camilla y silla de ruedas. La adecuación exacta se confirma con contexto clínico-operativo en asesoría I-ME."}], "preguntas_frecuentes_en": [{"q": "How do I quote MTP Series Floor-Mounted Radiographic System for my institution?", "a": "Request a quote on this page or via I-ME WhatsApp. We confirm availability, lead time and manufacturer documentation."}, {"q": "Is there a PDF datasheet for MTP Series Floor-Mounted Radiographic System?", "a": "No PDF is published on this web sheet yet. I-ME obtains the official manufacturer datasheet when quoting — without inventing specs."}, {"q": "What floor/service problem does MTP Series Floor-Mounted Radiographic System address?", "a": "Floor-mounted radiographic system with a four-way floating table, electrically synchronized tracking between the X-ray tube and detector, and a rotating column compatible with stretcher and wheelchair exams. Exact fit is confirmed with clinical-operational context in I-ME advisory."}], "seo_keywords_es": ["sistema radiográfico de piso mtp", "cotización", "equipo hospitalario", "I-ME Colombia"], "seo_keywords_en": ["mtp series floor-mounted radiographic system", "quote", "hospital equipment", "I-ME Colombia"], "enriquecimiento": {"tipo": "sin_ficha_pdf", "fecha": "2026-10-18", "nota": "Landing ligera sin inventar specs; PDF pendiente de fabricante"}}'::jsonb
