UPDATE public.productos SET
  descripcion_larga_es = 'El sistema Fanghua dispone de detector de panel plano de gran formato con resolución espacial orientada a la visualización de microcalcificaciones. La tomosíntesis permite la reconstrucción tomográfica de cortes del parénquima mamario, reduciendo la superposición tisular en mamas densas. La colimación motorizada inteligente acota el campo de exposición al área anatómica de interés, mientras que el control automático de exposición optimiza la dosis. El ánodo de tungsteno opcional contribuye a la reducción de dosis en pacientes con tejido sensible.',
  descripcion_larga_en = 'The Fanghua system features a large-format flat-panel detector with spatial resolution oriented toward the visualization of microcalcifications. Tomosynthesis allows tomographic reconstruction of breast parenchyma slices, reducing tissue overlap in dense breasts. The intelligent motorized collimation limits the exposure field to the anatomical area of interest, while automatic exposure control optimizes dose. The optional tungsten target contributes to dose reduction in patients with sensitive tissue.',
  atributos = COALESCE(atributos, '{}'::jsonb) || '{"beneficios_es": ["Sistema de mamografía digital con detector de panel plano de gran formato, capacidad de tomosíntesis, colimación motorizada inteligente y control automático de exposición, con ánodo opcional de tungsteno para reducción de dosis."], "beneficios_en": ["Digital mammography system with a large-format flat-panel detector, tomosynthesis capability, intelligent motorized collimation and automatic exposure control, with an optional tungsten target for dose reduction."], "valor_es": "Sistema de Mamografía Digital Fanghua para evaluación institucional; Sistema de mamografía digital con detector de panel plano de gran formato, capacidad de tomosíntesis, colimación motorizada inteligente y control automático de exposición, con ánodo opcional de tungsteno para reducción de dosis.. Cotización y validación de ficha con I-ME; sin inventar prestaciones no documentadas.", "valor_en": "Fanghua Series Digital Mammography System for institutional evaluation; Digital mammography system with a large-format flat-panel detector, tomosynthesis capability, intelligent motorized collimation and automatic exposure control, with an optional tungsten target for dose reduction.. Quoting and datasheet validation with I-ME; no undocumented claims.", "preguntas_frecuentes_es": [{"q": "¿Cómo cotizar Sistema de Mamografía Digital Fanghua para mi institución?", "a": "Solicite cotización en esta página o por WhatsApp I-ME. Indicamos disponibilidad, plazo y documentación del fabricante."}, {"q": "¿Hay ficha técnica PDF de Sistema de Mamografía Digital Fanghua?", "a": "En este momento no hay PDF publicado en la ficha web. I-ME gestiona la ficha oficial del fabricante al cotizar, sin inventar especificaciones."}, {"q": "¿Qué problema resuelve Sistema de Mamografía Digital Fanghua en piso o servicio?", "a": "Sistema de mamografía digital con detector de panel plano de gran formato, capacidad de tomosíntesis, colimación motorizada inteligente y control automático de exposición, con ánodo opcional de tungsteno para reducción de dosis. La adecuación exacta se confirma con contexto clínico-operativo en asesoría I-ME."}], "preguntas_frecuentes_en": [{"q": "How do I quote Fanghua Series Digital Mammography System for my institution?", "a": "Request a quote on this page or via I-ME WhatsApp. We confirm availability, lead time and manufacturer documentation."}, {"q": "Is there a PDF datasheet for Fanghua Series Digital Mammography System?", "a": "No PDF is published on this web sheet yet. I-ME obtains the official manufacturer datasheet when quoting — without inventing specs."}, {"q": "What floor/service problem does Fanghua Series Digital Mammography System address?", "a": "Digital mammography system with a large-format flat-panel detector, tomosynthesis capability, intelligent motorized collimation and automatic exposure control, with an optional tungsten target for dose reduction. Exact fit is confirmed with clinical-operational context in I-ME advisory."}], "seo_keywords_es": ["sistema de mamografía digital fanghua", "cotización", "equipo hospitalario", "I-ME Colombia"], "seo_keywords_en": ["fanghua series digital mammography system", "quote", "hospital equipment", "I-ME Colombia"], "enriquecimiento": {"tipo": "sin_ficha_pdf", "fecha": "2026-10-18", "nota": "Landing ligera sin inventar specs; PDF pendiente de fabricante"}}'::jsonb
