UPDATE public.productos SET
  descripcion_larga_es = 'El arco en C móvil HUA II integra un detector de panel plano (FPD) que proporciona imágenes digitales en tiempo real con elevada relación señal-ruido para procedimientos intraoperatorios. Su diseño modular y el sistema de movimiento contrarrestado permiten posicionamiento preciso alrededor del campo quirúrgico. El protocolo de baja dosis reduce la exposición acumulada en procedimientos prolongados.',
  descripcion_larga_en = 'The HUA II mobile C-arm integrates a flat-panel detector (FPD) that delivers real-time digital images with high signal-to-noise ratio for intraoperative procedures. Its modular design and counterbalanced movement system enable precise positioning around the surgical field. The low-dose protocol reduces cumulative exposure during lengthy procedures.',
