UPDATE public.productos SET
  descripcion_larga_es = 'Nebulizador concebido para acoplarse al compresor NUBE y generar partículas de aerosol adecuadas para terapias respiratorias. Permite la administración de medicamentos broncodilatadores y antiinflamatorios en pacientes con enfermedades obstructivas.',
